create table if not exists public.student_submission_checkpoints (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,item_type text not null check(item_type in ('College application','Scholarship')),item_id uuid not null,item_name text not null check(char_length(item_name) between 1 and 240),submitted_on date,portal_checked_on date,confirmation_saved boolean not null default false,follow_up_needed boolean not null default false,notes text not null default '' check(char_length(notes)<=3000),updated_at timestamptz not null default now(),unique(user_id,item_type,item_id));
alter table public.student_submission_checkpoints enable row level security;revoke all on public.student_submission_checkpoints from anon;grant select,insert,update,delete on public.student_submission_checkpoints to authenticated;
create policy "Students manage own submission checkpoints" on public.student_submission_checkpoints for all to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
